1	# Canonical tea-wrapped tools: stdin→stdout stream filters that *mutate*
2	# the byte/line stream (reorder, rewrite, select, reshape).
3	#
4	# Excluded on purpose:
5	#   tee, cat     — identity / fan-out, do not mutate stdout content
6	#   more, less   — interactive pagers
7	#   split/csplit — primarily write files
8	#   checksums, base64/base32 — digest/encode sinks, uncommon in filter pipes
9	#   dd, yes, seq — special / generators
10	#
11	# BusyBox ships the same applet names; we wrap the GNU/util-linux binaries
12	# that NixOS puts on PATH (hiPrio), which covers the busybox-shaped workflows.
13	
14	{ pkgs }:
15	
16	let
17	  cu = "${pkgs.coreutils}/bin";
18	  grep = "${pkgs.gnugrep}/bin";
19	  sed = "${pkgs.gnused}/bin";
20	  gawk = "${pkgs.gawk}/bin";
21	  # util-linux multi-output: prefer .bin when present
22	  ul = "${pkgs.util-linux.bin or pkgs.util-linux}/bin";
23	in
24	{
25	  # --- selection / slicing ---
26	  grep = "${grep}/grep";
27	  egrep = "${grep}/egrep";
28	  fgrep = "${grep}/fgrep";
29	  head = "${cu}/head";
30	  tail = "${cu}/tail";
31	  cut = "${cu}/cut";
32	
33	  # --- rewriting ---
34	  sed = "${sed}/sed";
35	  awk = "${gawk}/awk";
36	  gawk = "${gawk}/gawk";
37	  tr = "${cu}/tr";
38	  expand = "${cu}/expand";
39	  unexpand = "${cu}/unexpand";
40	  fmt = "${cu}/fmt";
41	  fold = "${cu}/fold";
42	  nl = "${cu}/nl";
43	  numfmt = "${cu}/numfmt";
44	
45	  # --- ordering / uniqueness ---
46	  sort = "${cu}/sort";
47	  uniq = "${cu}/uniq";
48	  shuf = "${cu}/shuf";
49	  tac = "${cu}/tac";
50	  rev = "${ul}/rev";
51	  tsort = "${cu}/tsort";
52	
53	  # --- columnar / paste ---
54	  paste = "${cu}/paste";
55	  join = "${cu}/join";
56	  column = "${ul}/column";
57	  col = "${ul}/col";
58	  colrm = "${ul}/colrm";
59	
60	  # --- dump / count (stream → representation) ---
61	  od = "${cu}/od";
62	  hexdump = "${ul}/hexdump";
63	  hd = "${ul}/hd";
64	  wc = "${cu}/wc";
65	
66	  # --- misc text transforms ---
67	  pr = "${cu}/pr";
68	  ptx = "${cu}/ptx";
69	  comm = "${cu}/comm";
70	}
