1	{
2	  description = "sh-tea — transparent pipeline stage logger (tee pun) for stdin→stdout filters; CLI is `tea` for short, `sh-tea` ships as an alias";
3	
4	  inputs = {
5	    nixpkgs.url = "github:NixOS/nixpkgs/nixos-26.05";
6	  };
7	
8	  outputs = { self, nixpkgs }:
9	  let
10	    system = "x86_64-linux";
11	    lib = nixpkgs.lib;
12	    pkgs = import nixpkgs { inherit system; };
13	
14	    filterTools = import ./tools.nix { inherit pkgs; };
15	    toolNames = lib.sort lib.lessThan (lib.attrNames filterTools);
16	
17	    toolsJson = pkgs.writeText "tea-tools.json" (builtins.toJSON filterTools);
18	
19	    defaultConfigToml =
20	      let
21	        toolSections = lib.concatMapStrings (name: ''
22	          [tools.${name}]
23	          enabled = true
24	        '') toolNames;
25	      in
26	      pkgs.writeText "tea-default-config.toml" ''
27	        # tea — transparent pipeline logger
28	        # Copied to $XDG_CONFIG_HOME/tea/config.toml on first use when missing.
29	
30	        [defaults]
31	        # When true, activate in interactive sessions (stderr is a TTY) without --tea.
32	        default-interactive = true
33	        # When true, ONLY --tea activates (ignore interactive + agentic auto-detect).
34	        manual-only = false
35	        # Append logs.csv to .gitignore when logging in a git work tree.
36	        update-gitignore = true
37	        # Keep at most this many rows in ./logs.csv (oldest dropped; .tea files removed).
38	        max-log-records = 20
39	        # Suppress the stderr blurb that announces the log path.
40	        quiet = false
41	        # Post-activation filter: drop the log if the stage's own elapsed
42	        # wall-clock time was under this many ms. Only applies to auto-detected
43	        # activation (agentic/interactive); --tea/TEA_FORCE always log.
44	        min-duration-ms = 5000
45	        # Restrict activation by git context (both false = anywhere).
46	        only-in-git-repos = false
47	        only-outside-git-repos = false
48	
49	        # Per-tool overrides inherit defaults; set enabled = false to disable a wrap.
50	        ${toolSections}
51	      '';
52	
53	    teaRust = pkgs.rustPlatform.buildRustPackage {
54	      pname = "tea";
55	      version = "0.1.0";
56	      src = lib.cleanSourceWith {
57	        src = ./.;
58	        filter =
59	          path: type:
60	          let
61	            base = baseNameOf path;
62	          in
63	          (lib.cleanSourceFilter path type)
64	          && !(builtins.elem base [
65	            "flake.nix"
66	            "flake.lock"
67	            "man"
68	            "tools.nix"
69	            "target"
70	            "tests"
71	          ]);
72	      };
73	      cargoLock.lockFile = ./Cargo.lock;
74	      doCheck = false;
75	      meta = with lib; {
76	        description = "Transparent pipeline stage logger for stdin→stdout filters";
77	        license = licenses.mit;
78	        mainProgram = "tea";
79	      };
80	    };
81	
82	    mkWrap =
83	      tool: real:
84	      pkgs.writeScriptBin tool ''
85	        #!${pkgs.runtimeShell}
86	        export TEA_DEFAULT_CONFIG="${defaultConfigToml}"
87	        export TEA_TOOLS_JSON="${toolsJson}"
88	        exec ${teaRust}/bin/tea-wrap ${tool} ${real} "$@"
89	      '';
90	
91	    wrapPkgs = lib.mapAttrsToList (name: real: mkWrap name real) filterTools;
92	
93	    teaCli = pkgs.writeScriptBin "tea" ''
94	      #!${pkgs.runtimeShell}
95	      export TEA_DEFAULT_CONFIG="${defaultConfigToml}"
96	      export TEA_TOOLS_JSON="${toolsJson}"
97	      exec ${teaRust}/bin/tea "$@"
98	    '';
99	
100	    # sh-tea is a plain alias for tea — same CLI, same env vars, same config —
101	    # kept around so the project name also works as a command.
102	    teaAlias = pkgs.writeScriptBin "sh-tea" ''
103	      #!${pkgs.runtimeShell}
104	      export TEA_DEFAULT_CONFIG="${defaultConfigToml}"
105	      export TEA_TOOLS_JSON="${toolsJson}"
106	      exec ${teaRust}/bin/tea "$@"
107	    '';
108	
109	    teaMan = pkgs.runCommand "tea-man" { } ''
110	      mkdir -p $out/share/man/man1
111	      cp ${./man/tea.1} $out/share/man/man1/tea.1
112	      ln -s tea.1 $out/share/man/man1/sh-tea.1
113	    '';
114	
115	    # Completions: generate fish loop + bash complete lines from toolNames.
116	    fishCompletion = pkgs.writeText "tea.fish" (
117	      ''
118	        # fish completions for tea wrappers — additive flags only
119	        for cmd in ${lib.concatStringsSep " " toolNames}
120	            complete -c $cmd -l tea -d 'tea: enable transparent pipeline logging'
121	            complete -c $cmd -l no-tea -d 'tea: disable transparent pipeline logging'
122	            complete -c $cmd -l coffee -d 'tea: disable transparent pipeline logging (alias)'
123	        end
124	
125	      ''
126	      + lib.concatMapStrings (cmd: ''
127	        complete -c ${cmd} -f
128	        complete -c ${cmd} -n __fish_use_subcommand -a last -d 'Print path of most recent logfile'
129	        complete -c ${cmd} -n __fish_use_subcommand -a list -d 'Print logs.csv'
130	        complete -c ${cmd} -n __fish_use_subcommand -a show -d 'Print a logfile (optional id)'
131	        complete -c ${cmd} -n __fish_use_subcommand -a config -d 'Ensure/print config.toml path'
132	        complete -c ${cmd} -n __fish_use_subcommand -a which -d 'Debug activation for a tool'
133	        complete -c ${cmd} -n '__fish_seen_subcommand_from which' -a '${lib.concatStringsSep " " toolNames}'
134	      '') [ "tea" "sh-tea" ]
135	    );
136	
137	    bashCompletion = pkgs.writeText "tea.bash" (
138	      ''
139	        # bash completions for tea/sh-tea CLI + light --tea/--coffee hints on wrappers.
140	        _tea_cli() {
141	          local cur="''${COMP_WORDS[COMP_CWORD]}"
142	          local prev="''${COMP_WORDS[COMP_CWORD-1]}"
143	          if [[ $COMP_CWORD -eq 1 ]]; then
144	            COMPREPLY=( $(compgen -W "last list show config which -h --help" -- "$cur") )
145	            return
146	          fi
147	          if [[ $prev == which ]]; then
148	            COMPREPLY=( $(compgen -W "${lib.concatStringsSep " " toolNames}" -- "$cur") )
149	            return
150	          fi
151	        }
152	
153	        _tea_wrap_flags() {
154	          local cur="''${COMP_WORDS[COMP_CWORD]}"
155	          case "$cur" in
156	            --tea*|--no-tea*|--coffee*|--cof*)
157	              COMPREPLY=( $(compgen -W "--tea --no-tea --coffee" -- "$cur") )
158	              ;;
159	          esac
160	        }
161	
162	        complete -F _tea_cli tea
163	        complete -F _tea_cli sh-tea
164	      ''
165	      + lib.concatMapStrings (name: ''
166	        complete -F _tea_wrap_flags -o bashdefault -o default ${name}
167	      '') toolNames
168	    );
169	
170	    teaCompletions = pkgs.runCommand "tea-completions" { } ''
171	      mkdir -p $out/share/bash-completion/completions
172	      mkdir -p $out/share/fish/vendor_completions.d
173	      cp ${bashCompletion} $out/share/bash-completion/completions/tea
174	      cp ${bashCompletion} $out/share/bash-completion/completions/sh-tea
175	      ${lib.concatMapStrings (name: ''
176	        cp ${bashCompletion} $out/share/bash-completion/completions/${name}
177	      '') toolNames}
178	      cp ${fishCompletion} $out/share/fish/vendor_completions.d/tea.fish
179	      cp ${fishCompletion} $out/share/fish/vendor_completions.d/sh-tea.fish
180	    '';
181	
182	    teaHooks = pkgs.runCommand "tea-hooks" { } ''
183	      mkdir -p $out/share/fish/vendor_conf.d $out/share/fish/vendor_functions.d
184	      cp ${./hooks/grep.fish} $out/share/fish/vendor_functions.d/grep.fish
185	      cp ${./hooks/tea-user-pipe.fish} $out/share/fish/vendor_conf.d/tea-user-pipe.fish
186	    '';
187	
188	    teaPkg = pkgs.symlinkJoin {
189	      name = "tea-0.1.0";
190	      paths = [ teaCli teaAlias teaMan teaCompletions teaHooks ] ++ wrapPkgs;
191	      meta = with lib; {
192	        description = "Transparent pipeline stage logger for stdin→stdout filters";
193	        mainProgram = "tea";
194	        license = licenses.mit;
195	      };
196	    };
197	  in
198	  {
199	    overlays.default = final: prev: {
200	      sh-tea = self.packages.${prev.system}.sh-tea;
201	    };
202	
203	    packages.${system}.sh-tea = lib.hiPrio teaPkg;
204	
205	    devShells.${system}.default = pkgs.mkShell {
206	      packages = with pkgs; [
207	        cargo
208	        rustc
209	        gcc
210	        rust-analyzer
211	      ];
212	    };
213	  };
214	}
