1	{
2	  # sh-tea — transparent pipeline stage logger (tee pun). scout module.
3	  # Thin import of the standalone sh-tea flake (github:mikenrafter/sh-tea);
4	  # see that repo for the actual Rust CLI + packaging logic.
5	  # home-files drops a minimal ~/.config/tea/config.toml (just the keys this
6	  # host wants to pin — tea's own Rust-level defaults fill in the rest, see
7	  # apply_raw() in that repo's src/lib.rs).
8	  #
9	  # `inputs ? nix-scout` gates scout/home: true under nix-scout eval/switch,
10	  # false under flakelet path eval — facets stay definitionally exclusive.
11	
12	  inputs.nixpkgs.url = "github:NixOS/nixpkgs/nixos-26.05";
13	  inputs.nix-scout.url = "github:mikenrafter/nix-scout";
14	  inputs.nix-scout.inputs.nixpkgs.follows = "nixpkgs";
15	  inputs.sh-tea.url = "github:mikenrafter/sh-tea";
16	  inputs.sh-tea.inputs.nixpkgs.follows = "nixpkgs";
17	
18	  outputs = { nixpkgs, ... }@inputs:
19	  let
20	    system = "x86_64-linux";
21	    lib = nixpkgs.lib;
22	  in
23	  lib.optionalAttrs (inputs ? nix-scout) (
24	    let
25	      pkgs = import nixpkgs {
26	        inherit system;
27	        overlays = [ inputs.sh-tea.overlays.default ];
28	      };
29	
30	      # Host default: don't bother logging auto-activated stages that finish
31	      # in under 5s — only worth a paper trail if something upstream was
32	      # actually slow (nix build/eval, nixos-rebuild, ...). Doesn't apply to
33	      # --tea/TEA_FORCE, which always log regardless of duration.
34	      configToml = pkgs.writeText "tea-config.toml" ''
35	        [defaults]
36	        min-duration-ms = 5000
37	      '';
38	
39	      homeFiles = pkgs.runCommand "scout-sh-tea-home" { } ''
40	        mkdir -p $out/home-files/.config/tea
41	        cp ${configToml} $out/home-files/.config/tea/config.toml
42	      '';
43	    in {
44	      # scout
45	      # home
46	      # symlinkJoin (not buildEnv): buildEnv's pathsToLink symlinks whole
47	      # top-level dirs (home-files/.config would be a directory symlink),
48	      # but nix-scout's apply-hm.sh walks home-files with plain `find` (no
49	      # -L) expecting real directories with symlinks only at leaf files —
50	      # exactly what symlinkJoin's deep merge produces. See break-lock's
51	      # scout module for the same pattern.
52	      packages.${system}.scout = pkgs.symlinkJoin {
53	        name = "scout-sh-tea";
54	        paths = [
55	          pkgs.sh-tea
56	          homeFiles
57	        ];
58	      };
59	    }
60	  ) // {
61	    # flakelet
62	  };
63	}
