1	//! tea-wrap TOOL REAL_BIN [args...] — transparent tee for pipeline stages.
2	
3	use std::io::{self, Write};
4	use std::os::unix::fs::PermissionsExt;
5	use std::os::unix::process::CommandExt;
6	use std::path::Path;
7	use std::process::{Command, Stdio};
8	
9	use tea::{
10	    announce, copy_stdin_to_proc_and_log, discover_pipeline_siblings, evaluate_activation,
11	    load_config, load_tools, make_logfile_path, register_log, strip_tea_flags, tool_config,
12	    ActivationContext, ActivationOutcome, Config, ToolCfg,
13	};
14	
15	fn passthrough_exec(real: &str, args: &[String]) -> ! {
16	    let err = Command::new(real).args(args).exec();
17	    eprintln!("tea-wrap: exec failed: {err}");
18	    std::process::exit(127);
19	}
20	
21	fn run_wrapped(
22	    tool: &str,
23	    real: &str,
24	    args: &[String],
25	    tcfg: &ToolCfg,
26	    subject_to_min_duration: bool,
27	) -> i32 {
28	    let logfile = match make_logfile_path() {
29	        Ok(p) => p,
30	        Err(e) => {
31	            eprintln!("tea-wrap: logfile: {e}");
32	            return 1;
33	        }
34	    };
35	    let quiet = tcfg.quiet;
36	    let siblings = discover_pipeline_siblings();
37	
38	    let started = std::time::Instant::now();
39	
40	    let mut child = match Command::new(real)
41	        .args(args)
42	        .stdin(Stdio::piped())
43	        .stdout(Stdio::inherit())
44	        .stderr(Stdio::inherit())
45	        .spawn()
46	    {
47	        Ok(c) => c,
48	        Err(e) => {
49	            eprintln!("tea-wrap: spawn {real}: {e}");
50	            return 127;
51	        }
52	    };
53	
54	    let nbytes = {
55	        let mut log_f = match std::fs::OpenOptions::new()
56	            .write(true)
57	            .truncate(true)
58	            .open(&logfile)
59	        {
60	            Ok(f) => f,
61	            Err(e) => {
62	                eprintln!("tea-wrap: open logfile: {e}");
63	                let _ = child.kill();
64	                return 1;
65	            }
66	        };
67	        let mut proc_stdin = child.stdin.take().expect("piped stdin");
68	        match copy_stdin_to_proc_and_log(&mut proc_stdin, &mut log_f) {
69	            Ok(n) => n,
70	            Err(e) if e.kind() == io::ErrorKind::BrokenPipe => {
71	                // Should be rare (copy handles EPIPE on write); keep going.
72	                let _ = log_f.flush();
73	                0
74	            }
75	            Err(e) => {
76	                eprintln!("tea-wrap: copy stdin: {e}");
77	                let _ = child.kill();
78	                return 1;
79	            }
80	        }
81	    };
82	    // Dropping proc_stdin closes the pipe.
83	
84	    let rc = match child.wait() {
85	        Ok(status) => status.code().unwrap_or(1),
86	        Err(_) => 1,
87	    };
88	
89	    let elapsed = started.elapsed();
90	    if subject_to_min_duration && elapsed.as_millis() < tcfg.min_duration_ms as u128 {
91	        let _ = std::fs::remove_file(&logfile);
92	        return rc;
93	    }
94	
95	    match register_log(
96	        tool,
97	        args,
98	        &logfile,
99	        nbytes,
100	        rc,
101	        tcfg,
102	        None,
103	        Some(&siblings),
104	    ) {
105	        Ok(row) => announce(&row, quiet),
106	        Err(e) => eprintln!("tea-wrap: register log: {e}"),
107	    }
108	    rc
109	}
110	
111	fn main() {
112	    let argv: Vec<String> = std::env::args().skip(1).collect();
113	    if argv.len() < 2 {
114	        eprintln!("usage: tea-wrap TOOL REAL_BIN [args...]");
115	        std::process::exit(2);
116	    }
117	
118	    let tool = &argv[0];
119	    let real = &argv[1];
120	    let raw_args = &argv[2..];
121	
122	    let tools = load_tools();
123	    if !tools.iter().any(|t| t == tool) {
124	        eprintln!("tea-wrap: unsupported tool: {tool}");
125	        std::process::exit(2);
126	    }
127	
128	    let real_path = Path::new(real);
129	    let executable = real_path.is_file()
130	        && real_path
131	            .metadata()
132	            .map(|m| m.permissions().mode() & 0o111 != 0)
133	            .unwrap_or(false);
134	    if !executable {
135	        eprintln!("tea-wrap: real binary not executable: {real}");
136	        std::process::exit(127);
137	    }
138	
139	    let (passthrough, force_on, force_off) = strip_tea_flags(raw_args);
140	    let cfg: Config = load_config();
141	    let tcfg = tool_config(&cfg, tool);
142	
143	    let report = evaluate_activation(tool, &cfg, force_on, force_off, ActivationContext::current());
144	    if !report.activate {
145	        passthrough_exec(real, &passthrough);
146	    }
147	    let subject_to_min_duration = matches!(
148	        report.outcome,
149	        ActivationOutcome::ActivatedAgentic | ActivationOutcome::ActivatedInteractive
150	    );
151	
152	    let code = match std::panic::catch_unwind(|| {
153	        run_wrapped(tool, real, &passthrough, &tcfg, subject_to_min_duration)
154	    }) {
155	        Ok(rc) => rc,
156	        Err(_) => 1,
157	    };
158	
159	    // BrokenPipe on stdout is normal when downstream closes early.
160	    let _ = io::stdout().flush();
161	    std::process::exit(code);
162	}
