1	//! tea — inspect / manage transparent pipeline logs.
2	
3	use std::io::{self, Write};
4	use std::path::PathBuf;
5	use std::process;
6	
7	use tea::{
8	    ensure_user_config, evaluate_activation, last_row, list_rows, load_config, load_tools,
9	    tool_config, ActivationContext, ActivationOutcome, ActivationReport, Config, CSV_FIELDS,
10	};
11	
12	const USAGE: &str = "\
13	tea — transparent pipeline stage logger
14	
15	Wrappers shadow stdin→stdout filter utilities (grep, sort, sed, …). When
16	activated they copy stdin to a mktemp --suffix .tea file (usually under /tmp)
17	and index rows in ./logs.csv, then run the real command unchanged.
18	
19	Activation (first match wins):
20	  --coffee / --no-tea   force off
21	  --tea                 force on
22	  agentic user pipeline auto on (unless manual-only)
23	  interactive user pipeline auto on when default-interactive = true
24	
25	Config: ~/.config/tea/config.toml  (created on first use)
26	See:    man tea
27	";
28	
29	fn cmd_last() -> i32 {
30	    match last_row(None) {
31	        Some(row) => {
32	            println!("{}", row.get("logfile").map(|s| s.as_str()).unwrap_or(""));
33	            0
34	        }
35	        None => {
36	            eprintln!("tea: no log records in ./logs.csv");
37	            1
38	        }
39	    }
40	}
41	
42	fn cmd_list() -> i32 {
43	    let rows = list_rows(None);
44	    if rows.is_empty() {
45	        eprintln!("tea: no log records in ./logs.csv");
46	        return 1;
47	    }
48	    let mut wtr = csv::WriterBuilder::new()
49	        .terminator(csv::Terminator::Any(b'\n'))
50	        .from_writer(io::stdout());
51	    if wtr.write_record(CSV_FIELDS).is_err() {
52	        return 1;
53	    }
54	    for r in &rows {
55	        let vals: Vec<&str> = CSV_FIELDS
56	            .iter()
57	            .map(|k| r.get(*k).map(|s| s.as_str()).unwrap_or(""))
58	            .collect();
59	        if wtr.write_record(&vals).is_err() {
60	            return 1;
61	        }
62	    }
63	    let _ = wtr.flush();
64	    0
65	}
66	
67	fn cmd_show(id: Option<&str>) -> i32 {
68	    let rows = list_rows(None);
69	    if rows.is_empty() {
70	        eprintln!("tea: no log records in ./logs.csv");
71	        return 1;
72	    }
73	    let row = if let Some(want) = id {
74	        match rows.iter().find(|r| r.get("id").map(|s| s.as_str()) == Some(want)) {
75	            Some(r) => r,
76	            None => {
77	                eprintln!("tea: no record id={want}");
78	                return 1;
79	            }
80	        }
81	    } else {
82	        rows.last().unwrap()
83	    };
84	    let logfile = row.get("logfile").map(|s| s.as_str()).unwrap_or("");
85	    let mut path = PathBuf::from(logfile);
86	    if !path.is_absolute() {
87	        path = std::env::current_dir().unwrap_or_else(|_| PathBuf::from(".")).join(path);
88	    }
